const stages=['Primeiro contato','Agendamento','Documentos','Assinatura','Fechado'];
const initialLeads=[];
const demoLeadKeys=new Set(['Mariana Oliveira|(11) 99912-3456','Rafael Mendes|(11) 99876-1020','Camila Ferreira|(11) 98765-2211','João Pedro Santos|(11) 97654-8830','Ana Beatriz Costa|(11) 99123-7766','Lucas Almeida|(11) 96543-1010','Fernanda Lima|(11) 95555-1212']);
const removeDemoLeads=rows=>(Array.isArray(rows)?rows:[]).filter(lead=>!demoLeadKeys.has(`${lead.name||''}|${lead.phone||''}`));
const initialEvents=[];
const initialDocs=[{name:'Procuração ad judicia',type:'Procuração',updated:'Modelo · atualizado em 10 nov'},{name:'Declaração de Hipossuficiência',type:'Declaração',updated:'Modelo · atualizado em 10 nov'},{name:'Contrato de Prestação de Serviços e Honorários',type:'Contrato',updated:'Modelo · atualizado em 12 nov'}];
const legalCategories=['Trabalhista','Tributário','Cível · Consumidor e bancário','Previdenciário','Imobiliário','Penal/Criminal','Direito Armamentista'];
const SERVER_MODE=document.documentElement.dataset.serverMode==='true';
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('lc_'+k))||d}catch{return d}};
let leads=removeDemoLeads(get('leads',initialLeads)),events=get('events',initialEvents),docs=get('docs',initialDocs),cases=get('cases',[]),campaigns=get('campaigns',[]),legalLibrary=get('legalLibrary',[]),tasks=get('tasks',[]),archivedAnalysisData=get('analyses',[]),currentActor='Luana Cruz',currentView='inicio';
const content=document.querySelector('#content');
const views={inicio:'Visão geral',leads:'Leads',processos:'Processos',tarefas:'Tarefas',agenda:'Agenda',documentos:'Documentos',teses:'Teses e peças',campanhas:'Campanhas',conexoes:'Conexões'};
let csrfToken='',remoteVersion=0,saveQueue=Promise.resolve();
const snapshot=()=>({leads,events,docs,cases,campaigns,legalLibrary,tasks,analyses:archivedAnalysisData});
const save=()=>{if(SERVER_MODE){const data=JSON.parse(JSON.stringify(snapshot()));saveQueue=saveQueue.then(async()=>{const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({version:remoteVersion,data})});if(r.status===401){location.replace('/login');return}const payload=await r.json().catch(()=>({}));if(r.status===409){toast('Os dados foram alterados em outra sessão. Recarregue o painel antes de salvar novamente.');return}if(!r.ok)throw new Error(payload.error||'Falha ao salvar no servidor.');remoteVersion=payload.version}).catch(err=>toast(err.message||'Falha ao salvar no servidor.'));return}localStorage.setItem('lc_leads',JSON.stringify(leads));localStorage.setItem('lc_events',JSON.stringify(events));localStorage.setItem('lc_docs',JSON.stringify(docs));localStorage.setItem('lc_cases',JSON.stringify(cases));localStorage.setItem('lc_campaigns',JSON.stringify(campaigns));localStorage.setItem('lc_legalLibrary',JSON.stringify(legalLibrary));localStorage.setItem('lc_tasks',JSON.stringify(tasks));localStorage.setItem('lc_analyses',JSON.stringify(archivedAnalysisData));};
if(!SERVER_MODE){const stored=(()=>{try{return JSON.parse(localStorage.getItem('lc_leads')||'[]')}catch{return[]}})();if(removeDemoLeads(stored).length!==stored.length)localStorage.setItem('lc_leads',JSON.stringify(leads))}
const fmtToday=()=>new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
document.querySelector('#today').textContent=fmtToday();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const head=(eyebrow,title,desc,action='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const btn=(label,action,cls='btn-primary',icon='＋')=>`<button class="btn ${cls}" data-action="${action}">${icon} ${label}</button>`;
function setView(view){currentView=view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));document.querySelector('#crumb').textContent=views[view];render()}
function render(){document.querySelector('#leadCount').textContent=leads.length;const count=document.querySelector('#taskCount');if(count)count.textContent=tasks.filter(t=>!['Concluída','Protocolada'].includes(t.status)).length;let page=({inicio:overviewPage,leads:leadsPage,processos:processesPage,tarefas:window.tasksPage,agenda:agendaPage,documentos:docsPage,teses:legalLibraryPage,campanhas:campaignPage,conexoes:connectionsPage}[currentView])();content.innerHTML=page;if(currentView==='inicio')loadJudicialNews()}
function overviewPage(){return `<header class="overview-masthead"><div><div class="eyebrow">LUANA CRUZ ADVOCACIA · PAINEL INTERNO</div><h1>Visão geral</h1></div><nav class="overview-shortcuts" aria-label="Acesso rápido"><button data-view="leads">Leads <span>→</span></button><button data-view="processos">Processos <span>→</span></button><button data-view="agenda">Agenda <span>→</span></button></nav></header><section class="news-desk"><div class="news-desk-head"><div><div class="eyebrow">ACOMPANHAMENTO INSTITUCIONAL</div><h2>Notícias do Judiciário</h2><p>Publicações oficiais recentes do Conselho Nacional de Justiça e do Supremo Tribunal Federal.</p></div><div class="news-tools"><span id="newsUpdated" class="news-updated">Carregando notícias…</span><button class="news-refresh" data-action="refresh-news" aria-label="Atualizar notícias">↻ Atualizar</button></div></div><div id="judicialNews" class="judicial-news-list"><div class="news-loading">Carregando publicações oficiais…</div></div><div class="news-source">Fontes oficiais: <a href="https://www.cnj.jus.br/agencia-cnj/noticias-do-judiciario/" target="_blank" rel="noopener noreferrer">Notícias do Judiciário · CNJ ↗</a><span>·</span><a href="https://noticias.stf.jus.br/" target="_blank" rel="noopener noreferrer">Notícias · STF ↗</a></div></section>`}
let newsTimer;
async function loadJudicialNews(){const list=document.querySelector('#judicialNews'),stamp=document.querySelector('#newsUpdated');if(!list)return;if(!SERVER_MODE){list.innerHTML='<div class="news-loading">O feed em tempo real estará disponível quando o painel estiver publicado no servidor.</div>';if(stamp)stamp.textContent='';return}list.innerHTML='<div class="news-loading">Buscando publicações oficiais…</div>';try{const response=await fetch('/api/news');const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível buscar notícias.');list.innerHTML=data.items.length?data.items.map((item,index)=>`<article class="judicial-news-item ${index===0?'featured':''}">${item.image?`<a class="news-image-link" href="${esc(item.link)}" target="_blank" rel="noopener noreferrer"><img class="news-image" src="${esc(item.image)}" alt="${esc(item.imageAlt||'Imagem oficial da notícia')}" loading="${index<2?'eager':'lazy'}"></a>`:''}<div class="news-story"><span class="news-source-label">${esc(item.source||'Agência CNJ')}</span><span class="news-date">${item.date?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(item.date)):''}</span><h3><a href="${esc(item.link)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a></h3><p>${esc(item.excerpt)}</p><a class="news-read-more" href="${esc(item.link)}" target="_blank" rel="noopener noreferrer">Ler notícia completa ↗</a></div></article>`).join(''):'<div class="news-loading">Nenhuma notícia encontrada na fonte oficial.</div>';if(stamp)stamp.textContent=`${data.stale?'Última atualização disponível · ': 'Atualizado às '}${new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(data.fetchedAt))}`}catch(err){list.innerHTML=`<div class="news-loading">${esc(err.message)} <a href="https://www.cnj.jus.br/agencia-cnj/noticias-do-judiciario/" target="_blank" rel="noopener noreferrer">Abrir Notícias do Judiciário · CNJ</a></div>`;if(stamp)stamp.textContent='Fonte temporariamente indisponível'}clearTimeout(newsTimer);newsTimer=setTimeout(()=>{if(currentView==='inicio')loadJudicialNews()},5*60*1000)}
function dashboard(){const active=leads.filter(l=>l.stage!=='Fechado').length,hot=leads.filter(l=>l.hot&&l.stage!=='Fechado').length,meet=leads.filter(l=>l.stage==='Agendamento').length,contracts=leads.filter(l=>l.stage==='Fechado').length;const cols=stages.map(s=>{const n=leads.filter(l=>l.stage===s).length;return `<div class="pipeline-col"><header>${s}<b>${n}</b></header><div class="pipeline-bar"><span style="width:${Math.min(100,n*20)}%"></span></div><small>${n?Math.round(n/leads.length*100):0}% dos leads</small></div>`}).join('');return `${head('SEGUNDA-FEIRA, 16 DE NOVEMBRO','Bom dia, Luana','Aqui está o resumo do seu escritório para hoje.',btn('Novo lead','new-lead'))}<div class="stats-grid"><div class="stat-card"><div class="stat-top">Leads em andamento <span class="stat-icon">◉</span></div><div class="stat-value">${active}</div><div class="stat-foot"><span class="trend">${hot} quentes</span> com maior intenção de contratação</div></div><div class="stat-card"><div class="stat-top">Reuniões agendadas <span class="stat-icon">▦</span></div><div class="stat-value">${meet}</div><div class="stat-foot">Próxima: <span class="trend">hoje, 09:30</span></div></div><div class="stat-card"><div class="stat-top">Contratos fechados <span class="stat-icon">✓</span></div><div class="stat-value">${contracts}</div><div class="stat-foot">Neste mês</div></div><div class="stat-card"><div class="stat-top">Prazos próximos <span class="stat-icon">◷</span></div><div class="stat-value">1</div><div class="stat-foot"><span style="color:var(--gold);font-weight:600">Requer atenção</span> nos próximos 2 dias</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Funil de atendimento</h2><p>Acompanhe cada oportunidade até o fechamento</p></div><button class="text-link" data-view="leads">Ver todos →</button></div><div class="pipeline">${cols}</div><div class="section-title"><h2>Leads quentes</h2><button class="text-link" data-view="leads">Ver lista →</button></div>${leads.filter(l=>l.hot&&l.stage!=='Fechado').slice(0,3).map(l=>`<div class="lead-mini"><div class="avatar">${esc(l.initials)}</div><div class="lead-mini-info"><strong>${esc(l.name)}</strong><small>${esc(l.area)} · ${esc(l.source)}</small></div><span class="score">${l.score} pts</span></div>`).join('')||'<div class="empty-state">Nenhum lead quente no momento.</div>'}</section><section class="panel"><div class="panel-head"><div><h2>Próximos compromissos</h2><p>Agenda do escritório</p></div><button class="text-link" data-view="agenda">Abrir agenda →</button></div><div class="agenda-list">${events.slice(0,4).map(eventRow).join('')}</div></section></div><div class="section-title"><h2>Canais de atendimento</h2><button class="text-link" data-view="conexoes">Configurar canais →</button></div><div class="connection-strip">${['WhatsApp','Instagram','Facebook','TikTok'].map((x,i)=>`<div class="connection-card"><span class="social-icon">${['W','◎','f','♪'][i]}</span><div><strong>${x}</strong><small>Conecte para centralizar</small></div><span class="connection-state"></span></div>`).join('')}</div>`}
function eventDate(e){if(e.date)return e.date;if(e.dueDate)return e.dueDate;const months={jan:'01',fev:'02',mar:'03',abr:'04',mai:'05',jun:'06',jul:'07',ago:'08',set:'09',out:'10',nov:'11',dez:'12'};return `2026-${months[e.month]||'11'}-${String(e.day||1).padStart(2,'0')}`}
function deadlineStatus(e){if(e.done)return'green';if(e.type!=='prazo')return'normal';const target=Date.parse(`${eventDate(e)}T00:00:00Z`),today=Date.parse(`${localISODate()}T00:00:00Z`),days=Math.ceil((target-today)/86400000);if(days<=1)return'red';if(days<=4)return'yellow';return'normal'}
function scheduleDeadlineRefresh(){const now=new Date(),next=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,2);setTimeout(()=>{if(currentView==='agenda')render();scheduleDeadlineRefresh()},Math.max(1000,next-now))}
function eventRow(e){const d=eventDate(e),[year,month,day]=d.split('-'),status=deadlineStatus(e);return `<div class="agenda-item ${e.type==='prazo'?`deadline-row deadline-${status}`:''}"><div class="agenda-date"><b>${day}</b><small>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${d}T12:00:00`)).replace('.','')}</small></div><div class="agenda-copy"><strong>${esc(e.title)} ${e.type==='prazo'?`<span class="deadline-tag">${e.done?'Concluído':status==='red'?'Vence em até 1 dia':status==='yellow'?'Vence em até 4 dias':'Prazo'}</span>`:''}</strong><small>${esc(e.time||'A definir')} · ${esc(e.type)} · ${d.split('-').reverse().join('/')}</small>${e.caseId?`<button class="text-link event-process-link" data-action="open-process" data-id="${e.caseId}">Processo ${esc(e.processNumber||'')} · ${esc(e.court||'')} · ${esc(e.system||'')} ↗</button>`:''}</div>${e.type==='prazo'?`<button class="btn ${e.done?'btn-outline':'btn-primary'} event-done" data-action="toggle-event-done" data-id="${e.id}">${e.done?'Reabrir':'Marcar feito'}</button><button class="btn btn-delete event-delete" data-action="delete-event" data-id="${e.id}">Excluir</button>`:''}<button class="btn btn-outline event-edit" data-action="edit-event" data-id="${e.id}">Editar</button></div>`}
function leadsPage(){return `${head('RELACIONAMENTO','Leads','Acompanhe contatos, identifique oportunidades e avance cada atendimento.',btn('Adicionar lead','new-lead'))}<div class="notice">Contatos de Instagram, Facebook, WhatsApp e TikTok só entrarão automaticamente após ativar as integrações em <button class="text-link" data-view="conexoes">Conexões</button>. Até lá, cadastre-os manualmente e escolha a origem correta.</div><div class="toolbar"><label class="search-box"><span>⌕</span><input id="leadSearch" placeholder="Buscar por nome, área ou telefone..."></label><select class="filter-select" id="stageFilter"><option value="">Todas as etapas</option>${stages.map(s=>`<option>${s}</option>`).join('')}</select><select class="filter-select" id="heatFilter"><option value="">Todos os leads</option><option value="hot">Só leads quentes</option></select><select class="filter-select" id="sourceFilter"><option value="">Todos os canais</option>${[...new Set(leads.map(l=>l.source))].map(s=>`<option>${esc(s)}</option>`).join('')}</select><button class="btn btn-outline" data-action="toggle-board">▤ <span id="boardLabel">Ver quadro</span></button></div><div id="leadList">${leadTable(leads)}</div><div class="section-title"><h2>Etapas do atendimento</h2><span class="badge gray">Arraste pelo menu de cada lead</span></div><div class="kanban">${stages.map(s=>`<div class="kanban-col" data-drop-stage="${s}"><div class="kanban-head">${s}<span>${leads.filter(l=>l.stage===s).length}</span></div>${leads.filter(l=>l.stage===s).map(l=>`<div class="kanban-card" draggable="true" data-lead-id="${l.id}"><strong class="lead-name" title="Clique duas vezes para editar">${esc(l.name)}</strong><button class="row-actions lead-delete" title="Excluir lead" data-action="delete-lead" data-id="${l.id}">Excluir</button><p>${esc(l.area)} · ${esc(l.source)}</p><footer>${l.hot?'<span class="hot-label">✦ Lead quente</span>':'<span>'+l.score+' pts</span>'}<span>${esc(l.date)}</span></footer></div>`).join('')}</div>`).join('')}</div>`}
function leadTable(items){if(!items.length)return '<div class="empty-state">Nenhum lead encontrado. Ajuste os filtros ou adicione um contato.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Contato</th><th>Área</th><th>Origem</th><th>Etapa</th><th>Potencial</th><th>Último contato</th><th></th></tr></thead><tbody>${items.map(l=>`<tr><td><div class="person-cell"><div class="avatar">${esc(l.initials)}</div><div><strong>${esc(l.name)}</strong><small>${esc(l.phone)}</small></div></div></td><td>${esc(l.area)}</td><td><select class="source-select filter-select" data-id="${l.id}">${['Instagram','Indicação','WhatsApp','TikTok','Facebook','Google','Site','E-mail','Outro',...new Set(leads.map(x=>x.source).filter(Boolean))].map(source=>`<option ${source===l.source?'selected':''}>${esc(source)}</option>`).join('')}</select></td><td><select class="stage-select filter-select" data-id="${l.id}">${stages.map(s=>`<option ${s===l.stage?'selected':''}>${s}</option>`).join('')}</select></td><td><span class="badge ${l.hot?'green':'gray'}">${l.hot?'✦ Quente':'Em análise'} · ${l.score}</span></td><td>${esc(l.date)}</td><td><button class="row-actions" title="Editar lead" data-action="edit-lead" data-id="${l.id}">Editar</button><button class="row-actions lead-delete" title="Excluir lead" data-action="delete-lead" data-id="${l.id}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`}
function processesPage(){const moves=cases.flatMap(c=>(c.movements||[]).map(m=>({...m,case:c}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `${head('ACOMPANHAMENTO','Processos','Cadastre processos, registre andamentos e gere prazos ligados à agenda.',btn('Adicionar processo','new-case'))}<div class="notice">ⓘ <b>Cadastro e andamentos manuais disponíveis.</b> A consulta automática depende de integração e não está ativa. O DataJud do CNJ oferece consulta pública de metadados de processos públicos, mas não substitui todas as funções dos sistemas de origem nem garante notificações em tempo real.</div><div class="integration-strip-note"><b>Dados do processo</b><span>Número · Tribunal · Sistema (PJe, eproc, e-SAJ etc.)</span></div><section class="panel"><div class="panel-head"><div><h2>Processos acompanhados</h2><p>Edite os dados ou registre um andamento para criar prazo na agenda</p></div><span class="badge gray">${cases.length} processos · manual</span></div><div id="cases">${cases.map(c=>`<article id="process-${c.id}" class="case-card"><div class="case-top"><div><strong>${esc(c.title||c.party||'Processo')}</strong><span class="case-num">${esc(c.number)}</span></div><span class="badge ${c.source==='tribunal'?'green':'gold'}">${c.source==='tribunal'?'Sincronizado':'Manual'}</span></div><div class="case-meta"><span>Tribunal: <b>${esc(c.court||'Não informado')}</b></span><span>Sistema: <b>${esc(c.system||'Não informado')}</b></span><span>Parte: <b>${esc(c.party||'Não informado')}</b></span></div>${c.note?`<p class="case-note">${esc(c.note)}</p>`:''}<div class="case-actions"><button class="btn btn-outline" data-action="edit-case" data-id="${c.id}">Editar processo</button><button class="btn btn-primary" data-action="new-movement" data-id="${c.id}">＋ Registrar andamento / prazo</button><button class="btn btn-outline" data-action="new-workflow-task" data-process-id="${c.id}">＋ Criar tarefa</button></div>${(c.movements||[]).length?`<div class="case-movements"><b>Andamentos registrados</b>${c.movements.slice().reverse().map(m=>`<div class="movement-row"><span>${esc(m.date||'')}</span><strong>${esc(m.title)}</strong>${m.deadline?`<span class="badge copper">Prazo ${esc(m.deadline)}</span>`:''}${m.taskId?`<button class="text-link" data-action="open-task" data-id="${m.taskId}">Abrir tarefa ↗</button>`:''}</div>`).join('')}</div>`:''}</article>`).join('')||'<div class="empty-state">▤<b>Nenhum processo cadastrado</b>Adicione manualmente o número, tribunal, sistema e cliente.</div>'}</div></section><div class="section-title"><h2>Movimentações recentes</h2><button class="text-link" data-view="agenda">Ver prazos na agenda →</button></div><section class="panel">${moves.length?moves.slice(0,8).map(m=>`<div class="list-row"><span class="row-icon">§</span><div class="list-row-content"><strong>${esc(m.title)}</strong><small>${esc(m.date)} · Processo ${esc(m.case.number)} · ${esc(m.case.court)} · ${esc(m.case.system)}</small></div>${m.eventId?`<button class="text-link" data-action="edit-event" data-id="${m.eventId}">Abrir prazo ↗</button>`:''}</div>`).join(''):'<div class="empty-state">Os andamentos cadastrados aparecerão aqui. Um prazo informado cria automaticamente um compromisso vinculado na Agenda.</div>'}</section><div class="section-title"><h2>Conexões processuais</h2></div><div class="notice">Push automático nacional: precisa de uma integração de servidor e regras por tribunal/sistema, além de monitoramento dos canais oficiais. A demonstração ainda não consulta nem recebe atualizações judiciais.</div>`}
let agendaMonth=new Date(2026,10,1);
function agendaPage(){const dates=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'],year=agendaMonth.getFullYear(),month=agendaMonth.getMonth(),first=new Date(year,month,1).getDay(),total=new Date(year,month+1,0).getDate(),today=localISODate(),cells=Array.from({length:42},(_,i)=>{const day=i-first+1,muted=day<1||day>total,date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,ev=events.filter(e=>eventDate(e)===date);return `<div class="calendar-cell ${muted?'muted':''} ${date===today?'today-cell':''}"><span>${muted?'':day}</span>${ev.slice(0,2).map(e=>`<span class="calendar-entry"><button class="calendar-event deadline-${deadlineStatus(e)}" data-action="edit-event" data-id="${e.id}">${esc(e.time||'')} · ${esc(e.title)}</button>${e.type==='prazo'?`<button class="calendar-delete" title="Excluir prazo" aria-label="Excluir prazo" data-action="delete-event" data-id="${e.id}">×</button>`:''}</span>`).join('')}</div>`}).join('');return `${head('ORGANIZAÇÃO','Agenda','Prazos manuais e gerados por andamentos, com vínculo ao processo.',`<div class="head-actions"><button class="btn btn-outline" data-action="google-calendar-connect">Conectar Google Agenda</button>${btn('Novo prazo / compromisso','new-event')}</div>`)}<div class="notice">ⓘ Agenda editável manualmente. Os prazos inseridos ao registrar um andamento ficam ligados ao processo, tribunal e sistema. A sincronização com Google Agenda não está ativa até configurar OAuth e um serviço de servidor.</div><div class="deadline-legend"><span><i class="legend-red"></i>Vence em até 1 dia</span><span><i class="legend-yellow"></i>Vence em até 4 dias</span><span><i class="legend-green"></i>Concluído</span><small>A cor é atualizada automaticamente pela data final.</small></div><section class="panel"><div class="calendar-head"><div><h2>${new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(agendaMonth)}</h2><small style="font-size:12px;color:var(--muted)">Horário de Brasília · selecione um compromisso para editar</small></div><div><button class="btn btn-outline" data-action="prev-month">‹</button> <button class="btn btn-outline" data-action="next-month">›</button></div></div><div class="calendar-grid">${dates.map(d=>`<div class="calendar-day-name">${d}</div>`).join('')}${cells}</div></section><div class="section-title"><h2>Compromissos e prazos</h2><span class="badge copper">${events.length} itens</span></div><section class="panel"><div class="agenda-list">${events.slice().sort((a,b)=>eventDate(a).localeCompare(eventDate(b))).map(eventRow).join('')||'<div class="empty-state">Sua agenda está livre. Adicione um compromisso ou registre prazo em um processo.</div>'}</div></section>`}
function docsPage(){return `${head('MODELOS E ARQUIVOS','Documentos','Edite modelos em um editor de texto, importe arquivos e baixe em Word.',btn('Novo documento','new-doc'))}<div class="notice">ⓘ Importe .docx ou .txt, edite o texto e salve no acervo. Para usar conteúdo de IA, gere o texto no serviço de sua preferência e cole no editor; a conexão automática com IA ainda não está configurada.</div><section class="panel"><div class="panel-head"><div><h2>Documentos do escritório</h2><p>Abra um modelo para continuar editando ou baixar em Word</p></div><span class="badge copper">${docs.length} documentos</span></div>${docs.map((d,i)=>`<div class="template-card"><div class="file-icon">▧</div><div><strong>${esc(d.name)}</strong><small>${esc(d.type)} · ${esc(d.updated)}</small></div><button class="btn btn-outline" data-action="use-doc" data-id="${i}">Editar</button><button class="btn btn-primary" data-action="download-doc" data-id="${i}">↓ Word</button></div>`).join('')||'<div class="empty-state">Nenhum documento salvo. Crie um modelo ou importe um arquivo Word.</div>'}</section><div class="section-title"><h2>Criar a partir de um tipo comum</h2></div><div class="connection-strip">${[['Procuração','Poderes para representação'],['Declaração de Hipossuficiência','Pedido de gratuidade'],['Contrato de honorários','Serviços e honorários']].map(d=>`<div class="connection-card"><span class="social-icon">▧</span><div><strong>${d[0]}</strong><small>${d[1]}</small></div><button class="text-link" data-action="quick-doc" data-type="${d[0]}">Criar →</button></div>`).join('')}</div>`}
function legalLibraryPage(){return `${head('ACERVO JURÍDICO','Teses e modelos de peças','Edite no editor, use um modelo pronto ou importe e baixe arquivos Word.',`<div class="head-actions"><input id="legalUpload" type="file" accept=".docx,.txt" hidden><button class="btn btn-outline" data-action="pick-legal-upload">↑ Upload Word</button>${btn('Nova tese ou peça','new-legal-entry')}</div>`)}<div class="notice">ⓘ Cada item pode ser editado com formatação, importado de Word e baixado em .docx. Modelos prontos abaixo abrem no editor e podem ser personalizados antes de salvar.</div><section class="panel ready-templates"><div class="panel-head"><div><h2>Começar por um modelo pronto</h2><p>Escolha uma estrutura para abrir no editor</p></div></div><div class="ready-template-grid">${[['Petição inicial','Estrutura editável de peça processual'],['Contestação','Estrutura editável para defesa'],['Tese jurídica','Organize fundamentos e aplicação ao caso']].map(([title,desc])=>`<button class="ready-template" data-action="legal-template" data-template="${title}"><span class="row-icon">▧</span><span><strong>${title}</strong><small>${desc}</small></span><b>＋</b></button>`).join('')}</div></section><div class="toolbar"><label class="search-box"><span>⌕</span><input id="legalSearch" placeholder="Buscar tese, peça ou palavra-chave..."></label><select class="filter-select" id="legalCategory"><option value="">Todas as matérias</option>${legalCategories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><span class="badge copper">${legalLibrary.length} itens</span></div><div id="legalItems">${legalEntryList(legalLibrary)}</div>`}
function legalEntryList(items){if(!items.length)return '<section class="panel"><div class="empty-state">§<b>Seu acervo começa aqui</b>Cadastre uma tese ou faça upload de uma peça Word.</div></section>';return `<div class="legal-entry-list">${items.map(entry=>{const text=entryText(entry);return `<article class="panel legal-entry"><div class="legal-entry-main"><span class="row-icon">${entry.kind==='Tese'?'§':'▧'}</span><div><span class="badge copper">${esc(entry.category)}</span><h3>${esc(entry.title)}</h3><small>${esc(entry.kind)} · Atualizado em ${esc(entry.updated)}</small><p>${esc(text.slice(0,170))}${text.length>170?'…':''}</p></div></div><div class="legal-entry-actions"><button class="btn btn-outline" data-action="edit-legal" data-id="${entry.id}">Editar</button><button class="btn btn-primary" data-action="download-legal" data-id="${entry.id}">↓ Download Word</button></div></article>`}).join('')}</div>`}
function entryText(entry){if(entry.contentHtml){const d=document.createElement('div');d.innerHTML=sanitizeEditorHtml(entry.contentHtml);return d.innerText||d.textContent||''}return entry.content||''}
function legalStarter(template){const pieces={"Petição inicial":['Modelo de peça','<p><b>AO JUÍZO [INDICAR]</b></p><p><b>[NOME DA PARTE]</b>, [qualificação], por sua advogada, apresenta a presente</p><h2>PETIÇÃO INICIAL</h2><p><b>1. DOS FATOS</b></p><p>[Descreva os fatos relevantes em ordem cronológica.]</p><p><b>2. DO DIREITO</b></p><p>[Indique os fundamentos jurídicos aplicáveis e desenvolva a argumentação.]</p><p><b>3. DOS PEDIDOS</b></p><p>a) [Pedido principal];<br>b) [Demais pedidos e requerimentos];<br>c) [Provas e valor da causa].</p><p>[Cidade], [data].</p><p>[Assinatura e OAB]</p>'],"Contestação":['Modelo de peça','<p><b>AO JUÍZO [INDICAR]</b></p><p>Processo nº [NÚMERO]</p><p><b>[NOME DA PARTE]</b>, já qualificada, apresenta</p><h2>CONTESTAÇÃO</h2><p><b>1. SÍNTESE DA DEMANDA</b></p><p>[Resuma os pedidos e a narrativa inicial.]</p><p><b>2. PRELIMINARES</b></p><p>[Indique e desenvolva as preliminares pertinentes, se houver.]</p><p><b>3. DO MÉRITO</b></p><p>[Apresente a versão dos fatos, fundamentos e impugnação específica.]</p><p><b>4. DOS PEDIDOS</b></p><p>[Requerimentos finais, provas e demais providências.]</p><p>[Cidade], [data].</p><p>[Assinatura e OAB]</p>'],"Tese jurídica":['Tese','<h2>TESE: [TEMA]</h2><p><b>QUESTÃO JURÍDICA</b></p><p>[Qual questão será analisada?]</p><p><b>FUNDAMENTOS NORMATIVOS</b></p><p>[Leis, dispositivos e princípios pertinentes.]</p><p><b>ARGUMENTAÇÃO</b></p><p>[Desenvolva a tese e registre precedentes ou referências para conferência.]</p><p><b>APLICAÇÃO AO CASO</b></p><p>[Relacione os fundamentos aos fatos e documentos do caso.]</p><p><b>CONCLUSÃO</b></p><p>[Síntese do entendimento e providência pretendida.]</p>']};const [kind,contentHtml]=pieces[template];return{title:template,kind,category:'Trabalhista',contentHtml}}
function campaignPage(){return `${head('DIVULGAÇÃO','Campanhas','Planeje e acompanhe suas ações de marketing.',btn('Nova campanha','new-campaign'))}<div class="notice">ⓘ Criação e publicação de anúncios dependem das contas e permissões de cada plataforma. Este painel organiza seus planos; não publica campanhas por conta própria.</div><div class="campaign-grid">${[...campaigns.map(c=>[c.platform,c.platform==='Instagram'?'◎':c.platform==='Facebook'?'f':c.platform==='TikTok'?'♪':'G',c.name,'Rascunho',c.budget||'—','—'])].map(c=>`<article class="campaign-card"><div class="campaign-head"><span class="platform-mark">${c[1]}</span><span class="badge gray">${c[3]}</span></div><h3>${esc(c[2])}</h3><p>${esc(c[0])} · Sem conexão ativa</p><div class="campaign-metrics"><div><b>${c[4]}</b><small>INVESTIMENTO</small></div><div><b>${c[5]}</b><small>CONTATOS</small></div></div></article>`).join('')||'<div class="empty-state"><b>Nenhuma campanha cadastrada</b>Crie uma campanha para organizar suas ações.</div>'}</div>`}
function connectionsPage(){return `${head('CANAIS E INTEGRAÇÕES','Conexões','Veja como trazer mensagens e comentários para o cadastro de Leads.', '')}<div class="notice"><b>Status atual: canais ainda não conectados.</b> Este front-end não recebe mensagens por conta própria. Depois de configurar as APIs oficiais e o servidor, os webhooks podem alimentar uma caixa de entrada; de lá, cada contato poderá ser convertido em Lead com origem e link da conversa.</div><section class="panel"><div class="panel-head"><div><h2>Canais de atendimento</h2><p>As conexões dependem de contas elegíveis, permissões aprovadas e um endpoint HTTPS no servidor</p></div><span class="badge gold">0 ativos</span></div><div class="integration-grid">${[['WhatsApp Business','W','Conta da WhatsApp Business Platform / Cloud API.','WhatsApp'],['Instagram','◎','Conta profissional, permissões para mensagens e comentários.','Instagram'],['Facebook','f','Página administrada, permissões de mensagens e feed.','Facebook'],['TikTok','♪','TikTok for Business e acesso aprovado às APIs de mensagens/comentários.','TikTok']].map(x=>`<article class="integration-card"><div class="integration-title"><span class="platform-mark">${x[1]}</span><strong>${x[0]}</strong><span class="connection-state"></span></div><p>${x[2]}</p><button class="btn btn-outline" data-action="connect" data-name="${x[3]}">Ver etapas para conectar</button></article>`).join('')}</div></section><div class="section-title"><h2>Como os contatos entram em Leads</h2></div><section class="panel lead-sync-steps"><div><b>1</b><strong>Mensagem ou comentário recebido</strong><small>A plataforma envia um evento autorizado ao servidor por webhook.</small></div><div><b>2</b><strong>Caixa de entrada central</strong><small>O sistema registra canal, perfil, texto permitido, data e link da conversa.</small></div><div><b>3</b><strong>Converter em Lead</strong><small>Com um clique, cria o Lead com a origem (Instagram, WhatsApp etc.) e abre o fluxo de atendimento.</small></div></section><div class="notice"><b>O que ainda falta para ativar:</b> domínio HTTPS e servidor para webhooks, cadastro de aplicativo de desenvolvedor em cada plataforma, OAuth/permissões, revisão de aplicativo quando exigida, armazenamento seguro de tokens e banco de dados. As plataformas só liberam eventos e dados previstos em suas APIs e permissões; não é possível capturar qualquer conversa de contas pessoais indiscriminadamente.</div><div class="section-title"><h2>Outros serviços</h2></div><div class="integration-grid">${[['Tribunais (DataJud / PJe)','§','Consulta e monitoramento dependem da API, do tribunal e do sistema.','Processos'],['Google Agenda','▦','Sincronização exige OAuth e backend; ainda não ativa.','Agenda'],['Google Ads','G','Organização de campanhas; publicação externa ainda não conectada.','Campanhas']].map(x=>`<article class="integration-card"><div class="integration-title"><span class="platform-mark">${x[1]}</span><strong>${x[0]}</strong></div><p>${x[2]}</p><button class="btn btn-outline" data-view="${x[3]==='Processos'?'processos':x[3]==='Agenda'?'agenda':'campanhas'}">Abrir ${x[3]}</button></article>`).join('')}</div><div class="section-title"><h2>Dados profissionais</h2></div><section class="panel"><div class="list-row"><span class="row-icon">§</span><div class="list-row-content"><strong>OAB/SP 415.473</strong><small>Informada para configuração futura do acompanhamento processual</small></div><span class="badge gold">Não conectado</span></div></section>`}
function openModal(title,desc,body,onSubmit){let modal=document.querySelector('#modal');modal.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${desc}</p></div><button class="modal-close" data-action="close-modal">×</button></div><form id="modalForm">${body}<div class="form-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Salvar</button></div></form>`;document.querySelector('#modalBackdrop').classList.add('open');document.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));document.querySelector('#modalBackdrop').classList.remove('open');render()}}
const field=(label,name,placeholder='',opts=null)=>`<div class="field"><label>${label}</label>${opts?`<select name="${name}" required>${opts.map(o=>`<option>${o}</option>`).join('')}</select>`:`<input name="${name}" placeholder="${placeholder}" ${name==='name'?'required':''}>`}</div>`;
function newLead(){openModal('Adicionar lead','Registre um novo contato interessado.',`<div class="form-grid">${field('Nome completo','name','Ex.: Maria Silva')}${field('Telefone / WhatsApp','phone','(11) 99999-9999')}${field('E-mail','email','cliente@exemplo.com')}${field('Área de interesse','area','Ex.: Direito do Trabalho')}${field('Canal de origem','source','', ['Instagram','Indicação','WhatsApp','TikTok','Facebook','Google','Site','E-mail','Outro'])}${field('Etapa atual','stage','',['Primeiro contato','Agendamento','Documentos','Assinatura','Fechado'])}${field('Potencial de contratação','score','', ['Alto','Médio','Em avaliação'])}<div class="field full"><label>Observações iniciais</label><textarea name="note" placeholder="Resumo do primeiro contato..."></textarea></div></div>`,f=>{let name=f.get('name');let score={'Alto':88,'Médio':62,'Em avaliação':40}[f.get('score')];leads.unshift({id:Date.now(),name,initials:name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase(),area:f.get('area')||'Não informado',source:f.get('source'),stage:f.get('stage'),score,hot:score>=80,date:'Hoje',phone:f.get('phone')||'—',email:f.get('email')||'',note:f.get('note')});save();toast('Lead adicionado ao seu painel')})}
function localISODate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function newEvent(existing=null){const e=existing||{},selectedCase=e.caseId||'';openModal(existing?'Editar compromisso':'Novo prazo ou compromisso',existing?'Edite as informações do compromisso.':'Você pode vincular um processo; os prazos gerados pelos andamentos já ficam vinculados automaticamente.',`<div class="form-grid"><div class="field full"><label>Descrição</label><input name="title" required value="${esc(e.title||'')}" placeholder="Ex.: Prazo para manifestação"></div><div class="field"><label>Data do prazo</label><input type="date" name="date" required value="${existing?eventDate(e):localISODate()}"></div><div class="field"><label>Horário / observação</label><input name="time" value="${esc(e.time||'') }" placeholder="Ex.: 14:00 ou até o fim do dia"></div><div class="field"><label>Tipo</label><select name="type">${['prazo','reunião','tarefa','audiência','outro'].map(t=>`<option ${e.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Vincular processo (opcional)</label><select name="caseId"><option value="">Sem processo vinculado</option>${cases.map(c=>`<option value="${c.id}" ${String(selectedCase)===String(c.id)?'selected':''}>${esc(c.number)} · ${esc(c.court)} · ${esc(c.system)}</option>`).join('')}</select></div><div class="field full"><label>Observações</label><textarea name="note">${esc(e.note||'')}</textarea></div></div>`,f=>{const linked=cases.find(c=>String(c.id)===String(f.get('caseId'))),date=f.get('date'),record={...e,id:e.id||Date.now(),date,title:f.get('title'),time:f.get('time')||'A definir',type:f.get('type'),note:f.get('note'),caseId:linked?.id||null,processNumber:linked?.number||'',court:linked?.court||'',system:linked?.system||''};if(existing)Object.assign(existing,record);else events.push(record);for(const c of cases)for(const m of c.movements||[])if(m.eventId===record.id){m.deadline=date}save();toast(existing?'Compromisso atualizado':'Compromisso adicionado à agenda')})}
function newCase(existing=null){const c=existing||{};openModal(existing?'Editar processo':'Adicionar processo',existing?'Atualize número, tribunal, sistema e dados da parte.':'Cadastre manualmente o processo e identifique o sistema judicial.',`<div class="form-grid"><div class="field"><label>Número do processo (CNJ)</label><input name="number" required value="${esc(c.number||'')}" placeholder="0000000-00.0000.0.00.0000"></div><div class="field"><label>Nome / assunto</label><input name="title" value="${esc(c.title||'')}" placeholder="Ex.: Ação previdenciária"></div><div class="field"><label>Tribunal</label><input name="court" value="${esc(c.court||'')}" placeholder="Ex.: TJSP, TRT-2, TRF-3"></div><div class="field"><label>Sistema</label><select name="system">${['PJe','eproc','e-SAJ','Projudi','Themis','Outro / não sei'].map(s=>`<option ${c.system===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Parte / cliente</label><input name="party" value="${esc(c.party||'')}" placeholder="Nome do cliente"></div><div class="field"><label>Link público do processo (opcional)</label><input name="url" value="${esc(c.url||'')}" placeholder="https://..."></div><div class="field full"><label>Observações</label><textarea name="note">${esc(c.note||'')}</textarea></div></div>`,f=>{const data={...c,id:c.id||Date.now(),number:f.get('number'),title:f.get('title'),court:f.get('court'),system:f.get('system'),party:f.get('party'),url:f.get('url'),note:f.get('note'),source:c.source||'manual',movements:c.movements||[]};if(existing)Object.assign(existing,data);else cases.unshift(data);for(const ev of events)if(ev.caseId===data.id){ev.processNumber=data.number;ev.court=data.court;ev.system=data.system}save();toast(existing?'Processo atualizado':'Processo cadastrado')})}
function newMovement(caseId){const c=cases.find(x=>x.id===Number(caseId));if(!c)return;openModal('Registrar andamento','Registre a movimentação e informe uma data para gerar automaticamente o prazo na Agenda.',`<div class="notice">Processo ${esc(c.number)} · ${esc(c.court||'Tribunal não informado')} · ${esc(c.system||'Sistema não informado')}</div><div class="form-grid"><div class="field full"><label>Andamento / providência</label><input name="title" required placeholder="Ex.: Intimação para manifestação"></div><div class="field"><label>Data do andamento</label><input name="date" type="date" value="${localISODate()}" required></div><div class="field"><label>Prazo final (se aplicável)</label><input name="deadline" type="date"></div><div class="field full"><label>Detalhes</label><textarea name="description" placeholder="Resumo do andamento e providência a tomar"></textarea></div></div>`,f=>{const movement={id:Date.now(),title:f.get('title'),date:f.get('date'),description:f.get('description'),deadline:f.get('deadline')||''};if(movement.deadline){const event={id:Date.now()+1,date:movement.deadline,title:`Prazo: ${movement.title}`,time:'Verificar prazo',type:'prazo',note:movement.description,caseId:c.id,processNumber:c.number,court:c.court,system:c.system,movementId:movement.id};movement.eventId=event.id;events.push(event)}c.movements=c.movements||[];c.movements.push(movement);save();toast(movement.deadline?'Andamento salvo e prazo criado na Agenda':'Andamento salvo')})}
function newDoc(){openDocEditor(null,{name:'',type:'Outro',contentHtml:''})}
function openDocEditor(index,seed={}){const existing=index===null?null:docs[index],doc=existing||seed;const body=`<div class="form-grid"><div class="field"><label>Nome do documento</label><input name="name" required value="${esc(doc.name||'')}" placeholder="Ex.: Procuração ad judicia"></div><div class="field"><label>Tipo</label><select name="type">${['Procuração','Declaração','Contrato','Petição','Outro'].map(t=>`<option ${doc.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full"><label>Importar conteúdo existente</label><input id="docImport" type="file" accept=".docx,.txt,text/plain,application/vnd.openxmlformats-officedocument.wordprocessingml.document"><small class="muted-note">O conteúdo importado será carregado no editor abaixo.</small></div><div class="field full"><label>Editor do documento</label><div class="word-toolbar"><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="underline"><u>U</u></button><button type="button" data-cmd="formatBlock" data-value="H2">Título</button><button type="button" data-cmd="insertUnorderedList">• Lista</button><button type="button" data-cmd="undo">↶</button><button type="button" data-cmd="redo">↷</button><button type="button" class="ai-paste-toggle">Colar texto de IA</button></div><div id="aiPasteWrap" class="ai-paste-wrap hidden"><textarea id="aiPaste" placeholder="Cole aqui o texto gerado ou revisado com IA."></textarea><button type="button" class="btn btn-outline" data-action="apply-ai-text">Inserir no documento</button></div><div id="wordEditor" class="word-editor" contenteditable="true" spellcheck="true">${sanitizeEditorHtml(doc.contentHtml||'')}</div></div></div>`;openModal(existing?'Editar documento':'Novo documento','Escreva como em um editor de texto, importe um modelo ou cole conteúdo preparado com IA.',body,f=>{const record={name:f.get('name').trim(),type:f.get('type'),updated:'Editado em '+new Intl.DateTimeFormat('pt-BR').format(new Date()),contentHtml:document.querySelector('#wordEditor').innerHTML};if(existing)Object.assign(existing,record);else docs.unshift(record);save();toast('Documento salvo no acervo')});document.querySelector('#modal').classList.add('editor-modal')}
function sanitizeEditorHtml(html){const template=document.createElement('template');template.innerHTML=String(html||'');const allowed=new Set(['P','DIV','BR','B','STRONG','I','EM','U','H1','H2','H3','UL','OL','LI']);const walk=node=>{[...node.childNodes].forEach(child=>{if(child.nodeType===1){if(!allowed.has(child.tagName)){child.replaceWith(document.createTextNode(child.textContent));return}for(const attr of [...child.attributes])child.removeAttribute(attr.name);walk(child)}else if(child.nodeType!==3)child.remove()})};walk(template.content);return template.innerHTML}
