function legalEntryForm(entry=null,seed={}){const isEdit=!!entry,item=entry||seed,initialHtml=item.contentHtml||((item.content||'').split(/\r?\n/).map(line=>`<p>${esc(line)||'<br>'}</p>`).join(''));const body=`<div class="form-grid"><div class="field full"><label>Título da tese ou peça</label><input name="title" required value="${esc(item.title||'')}" placeholder="Ex.: Petição inicial · horas extras"></div><div class="field"><label>Matéria</label><select name="category" required>${legalCategories.map(c=>`<option ${item.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Tipo de conteúdo</label><select name="kind"><option ${item.kind==='Modelo de peça'?'selected':''}>Modelo de peça</option><option ${item.kind==='Tese'?'selected':''}>Tese</option></select></div><div class="field full"><label>Upload de modelo Word (.docx) ou texto (.txt)</label><input id="legalEntryImport" type="file" accept=".docx,.txt"><small class="muted-note">O conteúdo do arquivo será aberto no editor para revisão.</small></div><div class="field full"><label>Editor da peça</label><div class="word-toolbar legal-toolbar"><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="underline"><u>U</u></button><button type="button" data-cmd="formatBlock" data-value="H2">Título</button><button type="button" data-cmd="insertUnorderedList">• Lista</button><button type="button" data-cmd="undo">↶</button><button type="button" data-cmd="redo">↷</button></div><div id="legalEditor" class="word-editor" contenteditable="true" spellcheck="true">${sanitizeEditorHtml(initialHtml)}</div></div></div>`;openModal(isEdit?'Editar tese ou peça':'Nova tese ou peça','Use a formatação, faça upload de um Word ou escreva diretamente no editor.',body,f=>{const html=document.querySelector('#legalEditor').innerHTML;const plain=entryText({contentHtml:html});const data={title:f.get('title').trim(),category:f.get('category'),kind:f.get('kind'),contentHtml:html,content:plain,updated:new Intl.DateTimeFormat('pt-BR').format(new Date())};if(isEdit)Object.assign(entry,data);else legalLibrary.unshift({id:Date.now(),...data});save();toast(isEdit?'Peça atualizada':'Peça salva no acervo')});document.querySelector('#modal').classList.add('editor-modal')}
function xmlEscape(text){return String(text??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function makeZipDocxFile(entry){const paragraphs=[`<w:p><w:pPr><w:pStyle w:val="Title"/></w:pPr><w:r><w:t>${xmlEscape(entry.title)}</w:t></w:r></w:p>`,`<w:p><w:r><w:rPr><w:b/><w:color w:val="A85C38"/></w:rPr><w:t>${xmlEscape(entry.category+' · '+entry.kind)}</w:t></w:r></w:p>`,`<w:p/>`,...(entry.content||'').split(/\r?\n/).map(line=>`<w:p><w:r><w:t xml:space="preserve">${xmlEscape(line)||' '}</w:t></w:r></w:p>`)].join('');const documentXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paragraphs}<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`;const files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>','_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>','word/document.xml':documentXml};const enc=new TextEncoder(),crcTable=makeCrcTable(),locals=[],centrals=[];let offset=0;for(const [name,txt] of Object.entries(files)){const n=enc.encode(name),data=enc.encode(txt),crc=crc32(data,crcTable),lh=new Uint8Array(30+n.length),lv=new DataView(lh.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,n.length,true);lh.set(n,30);locals.push(lh,data);const ch=new Uint8Array(46+n.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);ch.set(n,46);centrals.push(ch);offset+=lh.length+data.length}const centralSize=centrals.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,centrals.length,true);ev.setUint16(10,centrals.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);const blob=new Blob([...locals,...centrals,end],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),url=URL.createObjectURL(blob),a=document.createElement('a'),slug=entry.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'');a.href=url;a.download=`${slug||'modelo-juridico'}.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo Word baixado')}
function makeCrcTable(){const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t}
function crc32(bytes,table){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function makeDocx(entry){let plain=entry.content||'';if(entry.contentHtml){const box=document.createElement('div');box.innerHTML=sanitizeEditorHtml(entry.contentHtml);plain=[...box.querySelectorAll('p,div,h1,h2,h3,li')].map(x=>x.innerText||x.textContent).join('\n')||box.innerText||box.textContent}makeZipDocxFile({...entry,title:entry.title||entry.name||'Documento',category:entry.category||entry.type||'Documento',kind:entry.kind||'Modelo',content:plain})}
