function newCampaign(){openModal('Planejar campanha','Crie um rascunho para organizar seus próximos anúncios.',`<div class="form-grid">${field('Nome da campanha','name','Ex.: Trabalhista · novembro')}${field('Plataforma','platform','',['Google Ads','Instagram','Facebook','TikTok'])}${field('Objetivo','goal','',['Gerar contatos','Alcance','Engajamento','Tráfego para o site'])}${field('Orçamento previsto','budget','Ex.: R$ 500 / mês')}<div class="field full"><label>Descrição</label><textarea name="description" placeholder="Público, tema e observações..."></textarea></div></div>`,f=>{campaigns.unshift({name:f.get('name'),platform:f.get('platform'),goal:f.get('goal'),budget:f.get('budget')});save();toast('Rascunho de campanha criado')})}
function connect(name){const setup={WhatsApp:'Crie um app Meta for Developers, adicione WhatsApp Business Platform, registre e verifique o número, configure o webhook HTTPS para eventos de mensagens e guarde o token no servidor.',Instagram:'Use uma conta profissional e um app Meta com Instagram API. Autorize os escopos de mensagens/comentários aplicáveis e configure as assinaturas de webhook; acesso avançado e análise do app podem ser exigidos para uso por clientes.',Facebook:'Selecione a Página no app Meta, solicite pages_messaging e as permissões de feed/metadata necessárias, configure Webhooks para messages e feed e passe pela revisão de permissões para uso público.',TikTok:'Crie um app no TikTok for Business, obtenha acesso às Business Messaging/Comments APIs, autorize a conta e registre o callback HTTPS. A disponibilidade depende da aprovação, escopos e recursos habilitados para a conta.'}[name]||'Cadastre o aplicativo e autorize os escopos oficiais necessários; configure um callback HTTPS no servidor.';openModal(`Etapas para conectar ${name}`,'Este painel ainda não tem conexão externa ativa.',`<div class="connection-guide"><span class="badge gold">Não conectado</span><ol><li>${esc(setup)}</li><li>Hospede o endpoint de webhook em HTTPS e valide as assinaturas enviadas pela plataforma.</li><li>Armazene tokens e segredos somente no servidor, nunca neste código do navegador.</li><li>Normalize o evento e associe a conversa ao Lead pela origem. Se for novo contato, coloque na caixa de entrada para revisão antes de criar o Lead.</li></ol><p>Depois que o backend e as credenciais estiverem configurados, esta tela poderá iniciar o OAuth e exibir o status real.</p></div>`,()=>{});document.querySelector('#modalForm button[type="submit"]').textContent='Fechar'}
