document.addEventListener('click',e=>{let v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);return}let a=e.target.closest('[data-action]');if(!a)return;let action=a.dataset.action;if(action==='new-lead')newLead();if(action==='new-event')newEvent();if(action==='new-case')newCase();if(action==='new-doc')newDoc();if(action==='new-campaign')newCampaign();if(action==='connect')connect(a.dataset.name);if(action==='close-modal')document.querySelector('#modalBackdrop').classList.remove('open');if(action==='toggle-board'){let board=document.querySelector('.kanban');board?.classList.toggle('hidden');document.querySelector('#boardLabel').textContent=board?.classList.contains('hidden')?'Ver quadro':'Ocultar quadro'}if(action==='delete-lead'){const lead=leads.find(x=>x.id===Number(a.dataset.id));if(lead&&confirm('Excluir o lead '+lead.name+'?')){leads=leads.filter(x=>x.id!==lead.id);save();render();toast('Lead excluído')}}if(action==='edit-lead'){let l=leads.find(x=>x.id===Number(a.dataset.id));if(l)openModal(l.name,'Atualize os dados do contato.',`<div class="form-grid">${field('Nome completo','name',l.name)}${field('Telefone / WhatsApp','phone',l.phone)}${field('E-mail','email',l.email||'')}${field('Área','area',l.area)}<div class="field"><label>Origem</label><select name="source">${['Instagram','Indicação','WhatsApp','TikTok','Facebook','Google','Site','E-mail','Outro',...new Set(leads.map(x=>x.source).filter(Boolean))].map(source=>`<option ${source===l.source?'selected':''}>${esc(source)}</option>`).join('')}</select></div><div class="field"><label>Etapa</label><select name="stage">${stages.map(s=>`<option ${s===l.stage?'selected':''}>${s}</option>`).join('')}</select></div>${field('Potencial','score','', ['Alto','Médio','Em avaliação'])}<div class="field full"><label>Observações</label><textarea name="note">${esc(l.note)}</textarea></div></div>`,f=>{l.name=f.get('name');l.phone=f.get('phone');l.email=f.get('email');l.area=f.get('area');l.source=f.get('source');l.stage=f.get('stage');l.note=f.get('note');l.initials=l.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();save();toast('Lead atualizado')})}});
document.addEventListener('change',e=>{if(e.target.matches('.source-select')){const lead=leads.find(x=>x.id===Number(e.target.dataset.id));if(lead){lead.source=e.target.value;save();render();toast('Origem do lead atualizada')}}if(e.target.matches('.stage-select')){let l=leads.find(x=>x.id===Number(e.target.dataset.id));if(l){l.stage=e.target.value;save();render();toast('Etapa do lead atualizada')}}if(e.target.id==='stageFilter'||e.target.id==='heatFilter'||e.target.id==='sourceFilter')filterLeads()});
