document.addEventListener('dblclick',e=>{const card=e.target.closest('.kanban-card[data-lead-id]');if(!card)return;const lead=leads.find(x=>x.id===Number(card.dataset.leadId));if(lead){const button=document.querySelector('[data-action="edit-lead"][data-id="'+card.dataset.leadId+'"]');if(button)button.click()}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.kanban-card[draggable="true"]');if(card){e.dataTransfer.setData('text/plain',card.dataset.leadId);e.dataTransfer.effectAllowed='move'}});
