document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop-stage]');if(!col)return;e.preventDefault();const id=Number(e.dataTransfer.getData('text/plain')),lead=leads.find(x=>x.id===id),stage=col.dataset.dropStage;if(lead&&stages.includes(stage)&&lead.stage!==stage){lead.stage=stage;save();render();toast('Lead movido para '+stage)}});

document.addEventListener('input',e=>{if(e.target.id==='legalSearch')filterLegalLibrary()});
document.addEventListener('change',e=>{if(e.target.id==='legalCategory')filterLegalLibrary()});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='new-legal-entry')legalEntryForm();if(action==='legal-template')legalEntryForm(null,legalStarter(button.dataset.template));if(action==='edit-legal'){const item=legalLibrary.find(x=>x.id===Number(button.dataset.id));if(item)legalEntryForm(item)}if(action==='download-legal'){const item=legalLibrary.find(x=>x.id===Number(button.dataset.id));if(item)makeDocx(item)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),action=b.dataset.action;if(action==='delete-event'){const event=events.find(x=>x.id===id);if(event&&window.confirm(`Excluir o prazo “${event.title}” da Agenda?`)){events=events.filter(x=>x.id!==id);for(const c of cases)for(const m of c.movements||[])if(m.eventId===id){m.eventId=null;m.deadline=''}save();render();toast('Prazo excluído da Agenda')}}if(action==='toggle-event-done'){const event=events.find(x=>x.id===id);if(event){event.done=!event.done;event.doneAt=event.done?localISODate():'';save();render();toast(event.done?'Prazo marcado como concluído':'Prazo reaberto')}}if(action==='edit-case'){const c=cases.find(x=>x.id===id);if(c)newCase(c)}if(action==='new-movement')newMovement(id);if(action==='edit-event'){const event=events.find(x=>x.id===id);if(event)newEvent(event)}if(action==='prev-month'||action==='next-month'){agendaMonth.setMonth(agendaMonth.getMonth()+(action==='prev-month'?-1:1));render()}if(action==='open-process'){const c=cases.find(x=>x.id===id);if(c){setView('processos');setTimeout(()=>document.querySelector(`#process-${c.id}`)?.scrollIntoView({behavior:'smooth',block:'center'}),50)}}if(action==='google-calendar-connect')openModal('Google Agenda','A conexão ainda precisa ser configurada no servidor.',`<div class="notice">Para sincronizar alterações automaticamente, o aplicativo precisa de um projeto Google Cloud, OAuth do Google Calendar e um backend que grave as alterações e receba notificações. Essas credenciais não devem ser colocadas neste site estático. A API permite inserir, atualizar e observar eventos após autorização.</div><p style="font-size:12px;line-height:1.6;color:var(--muted)">Por enquanto, os eventos e prazos ficam salvos no painel. Nenhuma alteração é enviada ao Google Agenda.</p>`,()=>{})});
function filterLegalLibrary(){const q=(document.querySelector('#legalSearch')?.value||'').toLowerCase(),category=document.querySelector('#legalCategory')?.value||'';const list=legalLibrary.filter(x=>(!category||x.category===category)&&(!q||`${x.title} ${x.content} ${x.kind} ${x.category}`.toLowerCase().includes(q)));const box=document.querySelector('#legalItems');if(box)box.innerHTML=legalEntryList(list)}
function starterContent(type){return `<p><b>${esc(type)}</b></p><p>CLIENTE: [NOME COMPLETO], [nacionalidade], [estado civil], [profissão], inscrito(a) no CPF sob nº [CPF], residente e domiciliado(a) em [ENDEREÇO].</p><p>OUTORGADO/CONTRATADO: [DADOS DO ESCRITÓRIO / ADVOGADA].</p><p><b>OBJETO E FINALIDADE</b></p><p>[Descreva os poderes, serviços contratados ou finalidade deste documento.]</p><p><b>CLÁUSULAS</b></p><p>[Insira e revise as cláusulas aplicáveis ao caso concreto.]</p><p>[Cidade], [data].</p><p>____________________________________<br>[NOME / ASSINATURA]</p>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],.word-toolbar button,.legal-toolbar button,.ai-paste-toggle');if(!b)return;if(b.dataset.action==='use-doc')openDocEditor(Number(b.dataset.id));if(b.dataset.action==='download-doc'){const d=docs[Number(b.dataset.id)];if(d)makeDocx(d)}if(b.dataset.action==='quick-doc'){const type=b.dataset.type;openDocEditor(null,{name:type,type:type.includes('Declaração')?'Declaração':type.includes('Contrato')?'Contrato':'Procuração',contentHtml:starterContent(type)})}if(b.dataset.action==='pick-legal-upload')document.querySelector('#legalUpload')?.click();if(b.dataset.cmd){const editor=b.closest('.word-toolbar')?.parentElement.querySelector('[contenteditable="true"]');editor?.focus();document.execCommand(b.dataset.cmd,false,b.dataset.value||null)}if(b.classList.contains('ai-paste-toggle'))document.querySelector('#aiPasteWrap')?.classList.toggle('hidden');if(b.dataset.action==='apply-ai-text'){const text=document.querySelector('#aiPaste')?.value||'',editor=document.querySelector('#wordEditor');if(text&&editor){editor.innerHTML=text.split(/\r?\n/).map(line=>`<p>${esc(line)||'<br>'}</p>`).join('');document.querySelector('#aiPasteWrap').classList.add('hidden');toast('Texto inserido no editor')}}});
document.addEventListener('change',e=>{if(e.target.id==='docImport'||e.target.id==='legalEntryImport')importDocument(e.target.files?.[0]);if(e.target.id==='legalUpload'&&e.target.files?.[0]){const file=e.target.files[0];legalEntryForm(null,{title:file.name.replace(/\.(docx|txt)$/i,''),kind:'Modelo de peça'});setTimeout(()=>importDocument(file),0);e.target.value=''}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="refresh-news"]'))loadJudicialNews()});
function filterLeads(){let q=(document.querySelector('#leadSearch')?.value||'').toLowerCase(),stage=document.querySelector('#stageFilter')?.value||'',heat=document.querySelector('#heatFilter')?.value||'',source=document.querySelector('#sourceFilter')?.value||'';let filtered=leads.filter(l=>(!q||`${l.name} ${l.area} ${l.phone}`.toLowerCase().includes(q))&&(!stage||l.stage===stage)&&(!heat||l.hot)&&(!source||l.source===source));let box=document.querySelector('#leadList');if(box)box.innerHTML=leadTable(filtered)}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.addEventListener('click',async e=>{if(e.target.closest('[data-action="retry-app"]')){location.reload();return}if(!e.target.closest('[data-action="logout"]'))return;e.preventDefault();try{await fetch('/api/logout',{method:'POST',headers:{'X-CSRF-Token':csrfToken}})}finally{location.replace('/login')}});
async function startApp(){if(!SERVER_MODE){render();scheduleDeadlineRefresh();return}const logout=document.querySelector('#logoutButton');if(logout)logout.hidden=false;try{const csrfResponse=await fetch('/api/csrf');if(csrfResponse.status===401){location.replace('/login');return}if(!csrfResponse.ok)throw new Error('Não foi possível iniciar a sessão do escritório.');csrfToken=(await csrfResponse.json()).csrfToken;const stateResponse=await fetch('/api/state');if(stateResponse.status===401){location.replace('/login');return}if(!stateResponse.ok)throw new Error('Não foi possível carregar os dados do escritório.');const remote=await stateResponse.json();remoteVersion=remote.version;const remoteLeads=remote.data.leads||[];leads=removeDemoLeads(remoteLeads);const removedDemoLeadCount=remoteLeads.length-leads.length;events=remote.data.events||[];docs=remote.data.docs||[];cases=remote.data.cases||[];campaigns=remote.data.campaigns||[];legalLibrary=remote.data.legalLibrary||[];archivedAnalysisData=remote.data.analyses||[];tasks=remote.data.tasks||[];currentActor=remote.user?.username||'Luana Cruz';if(removedDemoLeadCount)save();render();scheduleDeadlineRefresh()}catch(err){content.innerHTML=`<section class="panel"><h2>Painel indisponível</h2><p>${esc(err.message)}</p><button class="btn btn-primary" data-action="retry-app">Tentar novamente</button></section>`}}
startApp();

